import ast,base64,hashlib,json
s=base64.b64decode('').decode('utf-8')
assert hashlib.sha256(s.encode()).hexdigest()=='78ef9c323259aa0e84000003c28a7250e213ae4f8420264055819f49292c3efe'
t=ast.parse(s,filename='rog_stager.py')
compile(t,'rog_stager.py','exec')
print(json.dumps({'file':'rog_stager.py','bytes':len(s.encode()),'sha256':hashlib.sha256(s.encode()).hexdigest(),'ast_and_compile_only':True,'module_executed':False,'host_calls':0,'syntax':'passed'},sort_keys=True))
